"""Accepts the four arguments either positionally (in the order
weights_path output_path rgb_path csv_path) or as --flags."""
p = argparse.ArgumentParser(description="Convert cell masks to polylines with MobileSAM.")
names = {
    "weights_path": "Path to MobileSAM weights (mobile_sam.pt).",
    "output_path": "Output folder (or .csv file path) for the refined masks.",
    "rgb_path": "Path to the RGB image.",
    "csv_path": "Path to the metadata CSV.",
}
for name, hlp in names.items():
    p.add_argument(f"pos_{name}", nargs="?", default=None, metavar=name, help=hlp)
for name, hlp in names.items():
    p.add_argument(f"--{name}", f"--{name.replace('_', '-')}", dest=name, type=str,
                   default=None, help=hlp)
a = p.parse_args()
for name in names:
    if getattr(a, name) is None:
        setattr(a, name, getattr(a, f"pos_{name}"))
    if getattr(a, name) is None:
        p.error(f"missing required argument: {name}")
return a
